def validate_abstract_methods(abc, *names):
    methodstubs = dict.fromkeys(names, lambda s, *args: 0)
    C = type('C', (abc,), methodstubs)
    C()
    for name in names:
        stubs = methodstubs.copy()
        del stubs[name]
        C = type('C', (abc,), stubs)
        try:
            C()
        except TypeError:
            pass

def validate_comparison(instance):
    ops = ['lt', 'gt', 'le', 'ge', 'ne', 'or', 'and', 'xor', 'sub']
    operators = {}
    for op in ops:
        name = '__' + op + '__'
        operators[name] = getattr(operator, name)

    class Other:

        def __init__(self):
            self.right_side = False

        def __eq__(self, other):
            self.right_side = True
            return True
        __lt__ = __eq__
        __gt__ = __eq__
        __le__ = __eq__
        __ge__ = __eq__
        __ne__ = __eq__
        __ror__ = __eq__
        __rand__ = __eq__
        __rxor__ = __eq__
        __rsub__ = __eq__
    for name, op in operators.items():
        if not hasattr(instance, name):
            continue
        other = Other()
        op(instance, other)
        assert other.right_side, ('assertTrue', other.right_side)

