            self.right_side = False

        def __eq__(self, other):
            self.right_side = True
            return True
        __lt__ = __eq__
        __gt__ = __eq__
        __le__ = __eq__
        __ge__ = __eq__
        __ne__ = __eq__
        __ror__ = __eq__
        __rand__ = __eq__
        __rxor__ = __eq__
        __rsub__ = __eq__
    for name, op in operators.items():
        if not hasattr(instance, name):
            continue
        other = Other()
        op(instance, other)
